// CRE Grade 3 (19 Nov 2026): the file had KICD outcomes only and no question families. 26 skills over the 22 sub-strands, each
// with two or more prerequisites (Grade 2 first: written as Grade 2 outcomes, they name the Grade 2 skill once Grade 2 is built),
// four misconceptions a child of eight really shows, and a teaching pack entry. Bible facts are those of the passages the KICD
// design names; nothing denominational is asked. Habits and performances (making right choices, drawing the family tree,
// practising honesty, dramatising, reporting abuse, cleanliness and chores, reciting the Lord's Prayer) are marked by the teacher
// with the KICD rubric. Lines that touch belief carry FAITH; child-safety lines carry SAFE. Merged by scripts/build-cre-grade.mjs 3.
import { B, P, FAITH, RULE } from './common.mjs';

const SAFE = 'To confirm by a CRE teacher and the school counsellor (SAFE: child-safety content, read first): a common error of young children, not traced to a study by the author.';
const S = (sub, id, name, outcomes, forms, mastery, pre, mis, pack, rubric) => ({ sub, id, name, outcomes, forms, mastery: mastery + RULE, thinking: ['recall', 'reasoning'], pre, mis, pack, ...(rubric ? { rubric } : {}) });

